    {
      "claim": "彩霞山是七玄门总门所在地，主峰落日峰设十三处哨卡。",
      "sourceIds": ["C1P08"]
    },
    {
      "claim": "岳堂主宣布选拔规则：能到炼骨崖顶者成为正式弟子，正午前未到但表现可圈可点者可收为记名弟子。",
      "sourceIds": ["C1P25"]
    },
    {
      "claim": "韩立不明记名弟子含义，只知要往前走爬山。",
      "sourceIds": ["C1P26"]
    },
    {
      "claim": "岳堂主说师兄们会在后面护住众人，不会出危险。",
      "sourceIds": ["C1P29"]
    },
    {
      "claim": "韩立进入竹林后，一名瘦长师兄紧随其后，韩立害怕不敢说话。",
      "sourceIds": ["C1P32"]
    },
    {
      "claim": "韩立在竹林段多次休息，前方也有孩童在休息，他随后继续赶路。",
      "sourceIds": ["C1P34", "C1P36"]
    }
  ]
